/// How many there are.
pub const SUBSTANTIAL_COUNT: usize = 1345;

/// Implements part of the substantial family.
///
/// What one routine does, if it is one of these.
#[must_use]
pub fn routine_at(routine: u32) -> Option<&'static Routine> {
    SUBSTANTIAL
        .binary_search_by_key(&routine, |held| held.routine)
        .ok()
        .map(|at| &SUBSTANTIAL[at])
}

/// Implements part of the substantial family.
///
/// How deep one routine goes.
#[must_use]
pub fn deepest(held: &Routine) -> u8 {
    held.steps.iter().map(|step| step.depth).max().unwrap_or(0)
}

/// Implements part of the substantial family.
///
/// How many calls the average step at one depth makes.
///
/// Falls with every level, in this table and in every other of its kind.
#[must_use]
pub fn calls_at_depth(depth: u8) -> f64 {
    let steps: Vec<&Step> = SUBSTANTIAL
        .iter()
        .flat_map(|held| held.steps.iter())
        .filter(|step| step.depth == depth)
        .collect();
    if steps.is_empty() {
        return 0.0;
    }
    let calls: usize = steps.iter().map(|step| step.calls.len()).sum();
    #[expect(
        clippy::cast_precision_loss,
        reason = "counts of a few thousand, well inside what a double holds exactly"
    )]
    {
        calls as f64 / steps.len() as f64
    }
}

/// Implements part of the substantial family.
///
/// Every call the routine makes, in the order the steps are written.
#[must_use]
pub fn calls_of(held: &Routine) -> Vec<u32> {
    held.steps
        .iter()
        .flat_map(|step| step.calls.iter().copied())
        .collect()
}

/// Implements part of the substantial family.
///
/// Whether a routine has a loop of either kind.
#[must_use]
pub fn has_a_loop(held: &Routine) -> bool {
    held.steps
        .iter()
        .any(|step| matches!(step.does, Does::Repeatedly | Does::RepeatedlyAtLeastOnce))
}

/// Implements part of the substantial family.
///
/// Whether a routine is a constructor.
#[must_use]
pub fn is_a_constructor(held: &Routine) -> bool {
    held.steps
        .iter()
        .any(|step| step.calls.contains(&MAKES_AN_INSTANCE))
        && held
            .steps
            .iter()
            .any(|step| step.calls.contains(&AFTER_IT_IS_MADE))
}

/// Implements part of the substantial family.
///
/// Every routine that is a constructor.
#[must_use]
pub fn constructors() -> Vec<&'static Routine> {
    SUBSTANTIAL
        .iter()
        .filter(|held| is_a_constructor(held))
        .collect()
}

/// Implements part of the substantial family.
///
/// Whether the two halves of a constructor sit in different steps.
#[must_use]
pub fn halves_are_apart(held: &Routine) -> bool {
    let makes = held
        .steps
        .iter()
        .position(|step| step.calls.contains(&MAKES_AN_INSTANCE));
    let finishes = held
        .steps
        .iter()
        .position(|step| step.calls.contains(&AFTER_IT_IS_MADE));
    match (makes, finishes) {
        (Some(one), Some(other)) => one != other,
        _ => false,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_count_is_what_the_table_holds() {
        assert_eq!(SUBSTANTIAL.len(), SUBSTANTIAL_COUNT);
    }

    #[test]
    fn the_table_is_sorted_so_it_can_be_searched() {
        assert!(
            SUBSTANTIAL
                .windows(2)
                .all(|pair| pair[0].routine < pair[1].routine)
        );
    }

    #[test]
    fn a_routine_can_be_found_by_its_address() {
        let known = SUBSTANTIAL[0].routine;

        assert!(routine_at(known).is_some());
        assert!(routine_at(0).is_none());
    }

    #[test]
    fn these_are_bigger_than_the_routines_in_the_other_tables() {
        let here = SUBSTANTIAL
            .iter()
            .map(|held| held.steps.len())
            .max()
            .expect("some");
        let there = crate::nested_routines::NESTED
            .iter()
            .map(|held| held.steps.len())
            .max()
            .expect("some");

        assert!(here > there, "{here} against {there}");
    }

    #[test]
    fn every_recorded_call_is_a_function_that_was_recovered() {
        for held in &SUBSTANTIAL {
            for call in held.steps.iter().flat_map(|step| step.calls.iter()) {
                assert!(
                    (FIRST_RECOVERED..=LAST_RECOVERED).contains(call),
                    "{call:#010X} in {:#010X}",
                    held.routine
                );
            }
        }
    }

    #[test]
    fn the_depths_of_a_routine_only_ever_step_down_by_one() {
        for held in &SUBSTANTIAL {
            let mut last = 0_u8;
            for step in held.steps {
                assert!(step.depth <= last + 1, "{:#010X}", held.routine);
                last = step.depth;
            }
        }
    }

    #[test]
    fn the_work_sits_at_the_top_and_thins_at_every_level() {
        // Level after level, without once going back up. Branching narrows what
        // is being decided; it does not carry the work.
        let mut last = calls_at_depth(0);
        assert!(last > 2.0, "{last}");
        for depth in 1..=6 {
            let here = calls_at_depth(depth);
            assert!(here < last, "depth {depth}: {here} against {last}");
            last = here;
        }
    }

    #[test]
    fn and_it_starts_higher_here_than_in_the_smaller_routines() {
        let here = calls_at_depth(0);
        let there = crate::nested_routines::calls_at_depth(0);

        assert!(here > there, "{here} against {there}");
    }

    #[test]
    fn a_depth_nothing_reaches_averages_nothing() {
        assert!((calls_at_depth(250) - 0.0).abs() < f64::EPSILON);
    }

    #[test]
    fn many_of_them_have_a_loop() {
        let looping = SUBSTANTIAL.iter().filter(|held| has_a_loop(held)).count();

        assert!(looping > SUBSTANTIAL.len() / 4, "{looping}");
    }

    #[test]
    fn some_of_them_are_constructors() {
        assert!(!constructors().is_empty());
    }

    #[test]
    fn and_in_every_one_the_two_halves_sit_in_different_steps() {
        // The fifth separate population in which this has held with no
        // exception at all.
        for held in constructors() {
            assert!(halves_are_apart(held), "{:#010X}", held.routine);
        }
    }

    #[test]
    fn the_calls_of_a_routine_come_back_in_the_order_they_are_written() {
        let held = SUBSTANTIAL
            .iter()
            .find(|held| calls_of(held).len() > 5)
            .expect("some routine makes several calls");
        let listed = calls_of(held);
        let straight: Vec<u32> = held
            .steps
            .iter()
            .flat_map(|step| step.calls.iter().copied())
            .collect();

        assert_eq!(listed, straight);
    }

    #[test]
    fn every_routine_calls_something_and_asks_something() {
        for held in &SUBSTANTIAL {
            assert!(!calls_of(held).is_empty(), "{:#010X}", held.routine);
            assert!(
                held.steps
                    .iter()
                    .any(|step| step.does != Does::Straightaway),
                "{:#010X}",
                held.routine
            );
        }
    }

    #[test]
    fn some_of_them_call_through_a_thunk() {
        let thunked = SUBSTANTIAL
            .iter()
            .filter(|held| held.through_a_thunk)
            .count();

        assert!(thunked > 0);
        assert!(thunked < SUBSTANTIAL.len() / 2);
    }

    #[test]
    fn every_routine_is_listed_once() {
        let mut routines: Vec<u32> = SUBSTANTIAL.iter().map(|held| held.routine).collect();
        let before = routines.len();
        routines.sort_unstable();
        routines.dedup();

        assert_eq!(routines.len(), before);
    }
}
